/*==========================================================================*/

NVFS_Status nvfs_size_is_valid(NVFS_Entry_Name const entry_name , UInt16 entry_size)
{
  UInt16 rd_size ;

  NVFS_Status status = NVFS_OK;

  #if NVFS_USE_OS == 1
  
  if(os_irq_executing)
  { 
	NVFS_EXCEPTION_REPORT(NVFS_ERR_INVALID_CALL);
  	
  	return NVFS_ERR_INVALID_CALL;
  }
  
  #endif

  status = nvfs_rd_size (entry_name , &rd_size) ;

  if(status == NVFS_OK)
    {
      if(rd_size != entry_size)
        {
          status  = NVFS_ERROR ;
        } 
    }

  return status ;
}


